create extension if not exists pgcrypto;
create table if not exists campaigns (id uuid primary key default gen_random_uuid(), name text not null, product text not null, target_market text not null, target_url text, goal text not null, budget_usdc numeric(18,6) not null default 25, spent_usdc numeric(18,6) not null default 0, status text not null default 'draft', created_at timestamptz not null default now());
create table if not exists leads (id uuid primary key default gen_random_uuid(), campaign_id uuid references campaigns(id) on delete cascade, company text not null, person_name text, role text, public_url text, evidence jsonb not null default '[]'::jsonb, fit_score integer, intent_score integer, intent text, contact_status text not null default 'unknown', outreach_status text not null default 'draft', created_at timestamptz not null default now());
create table if not exists agent_runs (id uuid primary key default gen_random_uuid(), campaign_id uuid references campaigns(id) on delete cascade, stage text not null, status text not null, input jsonb, output jsonb, created_at timestamptz not null default now());
create table if not exists payment_intents (id uuid primary key default gen_random_uuid(), campaign_id uuid references campaigns(id) on delete cascade, service text not null, amount_usdc numeric(18,6) not null, status text not null default 'awaiting_approval', network text not null default 'base-sepolia', justification text, provider_reference text, transaction_hash text, created_at timestamptz not null default now());
create index if not exists leads_campaign_score_idx on leads(campaign_id, intent_score desc);
create index if not exists agent_runs_campaign_idx on agent_runs(campaign_id, created_at desc);
create index if not exists payment_intents_campaign_idx on payment_intents(campaign_id, created_at desc);
